/**
 * The generated transcript module must match its source.
 *
 * C11 from the Phase 1 review: the extracted text was produced by hand with
 * pdftotext flags I typed once, and every evidence test depends on it. The
 * derived module is now generated by a committed script, and this test
 * regenerates it in memory and compares — so drift fails here rather than
 * silently changing what counts as a caller's words.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { buildModule } from '../../scripts/generate-transcripts.mjs';
import { ENQUIRY_DOCUMENT_TEXT } from '@/demo/transcripts.generated';
import { loadPhoneTranscripts } from '@/demo/transcripts';

const root = new URL('../../', import.meta.url);
const source = readFileSync(fileURLToPath(new URL('context/enquiries/enquiries-extracted.txt', root)), 'utf8');
const generated = readFileSync(fileURLToPath(new URL('src/demo/transcripts.generated.ts', root)), 'utf8');

describe('the generated transcript module', () => {
  it('matches what the script would write today', () => {
    expect(generated, 'run: node scripts/generate-transcripts.mjs').toBe(buildModule(source));
  });

  it('round-trips the source text exactly, byte for byte', () => {
    expect(ENQUIRY_DOCUMENT_TEXT).toBe(source);
  });

  it('kept the characters the quote matcher depends on', () => {
    expect(ENQUIRY_DOCUMENT_TEXT).toContain('—');
    expect(ENQUIRY_DOCUMENT_TEXT).toContain('₹');
  });

  it('still parses all twenty phone calls out of it', () => {
    expect(loadPhoneTranscripts().size).toBe(20);
  });
});
